package ca.canadavhs.snapmobile

import android.graphics.Bitmap
import androidx.room.Room
import androidx.work.Configuration
import androidx.work.testing.*
import ca.canadavhs.snapmobile.core.*
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.first
import org.json.*
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.*
import org.robolectric.annotation.*

@RunWith(RobolectricTestRunner::class)
@GraphicsMode(GraphicsMode.Mode.NATIVE)
@Config(sdk=[35],application=CaptureApplication::class)
class TrashTest {
 private val app get()=RuntimeEnvironment.getApplication() as CaptureApplication
 private lateinit var repo:CaptureRepository
 @Before fun setup() {WorkManagerTestInitHelper.initializeTestWorkManager(app,Configuration.Builder().setExecutor(java.util.concurrent.Executor {}).setTaskExecutor(SynchronousExecutor()).build());repo=CaptureRepository(app,Room.inMemoryDatabaseBuilder(app,CaptureJournal::class.java).allowMainThreadQueries().build()) {d->java.nio.channels.FileChannel.open(d.toPath(),java.nio.file.StandardOpenOption.READ).use {it.force(true)}};app.repository=repo;repo.preferences.edit().clear().putBoolean("barcode",false).commit()}
 @After fun close() {repo.journal.close()}
 private suspend fun item():InventoryRow {repo.start("Trash fixture","A1");val p=repo.reserve();val b=Bitmap.createBitmap(40,60,Bitmap.Config.ARGB_8888);repo.pendingFile(p.id).outputStream().use {b.compress(Bitmap.CompressFormat.JPEG,90,it)};b.recycle();repo.complete(p.id);return repo.journal.inventoryDao().item(p.groupId)!!}
 @Test fun recordDisappearsAndRecoveryPreservesIdentityAndOriginals():Unit=runBlocking {val a=item();val p=repo.dao.photos(a.groupId).single();repo.trashLocal("INVENTORY",a.groupId);assertTrue(repo.journal.inventoryDao().watchItems().first().isEmpty());assertTrue(repo.dao.watchPhotos().first().isEmpty());val t=repo.journal.trashDao().target("INVENTORY",a.groupId)!!;assertEquals(TRASH_RETENTION,t.expiresAt-t.deletedAt);assertEquals(p.sha256,hashFile(repo.original(p.id)));repo.restoreTrash(t.id);assertEquals(a.itemId,repo.journal.inventoryDao().watchItems().first().single().itemId);assertFalse(repo.dao.photos(a.groupId).single().deleted);assertFalse(repo.journal.inventoryDao().item(a.groupId)!!.ready)}
 @Test fun batchDeletionHidesChildrenAndRestoresAsFinishedWithoutStartingCapture():Unit=runBlocking {val a=item();val s=repo.dao.group(a.groupId).sessionId;repo.trashLocal("BATCH",s);assertTrue(repo.dao.watchSessions().first().isEmpty());assertTrue(repo.dao.watchGroups().first().isEmpty());assertNull(repo.dao.active());repo.restoreTrash(repo.journal.trashDao().target("BATCH",s)!!.id);assertTrue(repo.dao.watchSessions().first().single().finished);assertEquals(a.itemId,repo.journal.inventoryDao().watchItems().first().single().itemId);assertNull(repo.dao.active())}
 @Test fun singlePhotoDeletionIsIndependentAndCannotBeRecoveredAfterSevenDays():Unit=runBlocking {val a=item();val p=repo.dao.photos(a.groupId).single();repo.deletePhoto(p.id);assertTrue(repo.dao.watchPhotos().first().isEmpty());val t=repo.journal.trashDao().target("PHOTO",p.id)!!;repo.journal.openHelper.writableDatabase.execSQL("UPDATE trash_entries SET deletedAt=?,expiresAt=? WHERE id=?",arrayOf<Any>(System.currentTimeMillis()-TRASH_RETENTION-1,System.currentTimeMillis()-1,t.id));try {repo.restoreTrash(t.id);fail()} catch(_:IllegalStateException) {};assertTrue(repo.dao.photo(p.id).deleted);assertTrue(repo.journal.inventoryDao().watchItems().first().isNotEmpty())}
 @Test fun localDraftDeletionNeverChangesRemoteIdsAndRecoveryNeverRestartsWork():Unit=runBlocking {val a=item();val job=ShopifyJobRow(kind="CREATE_DRAFT",shopId="fixture",shop="fixture",broker="https://broker.example.invalid",connectionFingerprint="fixture",locationId="fixture",state="SUCCESS");repo.journal.shopifyDao().insert(job);val entry=ShopifyItemJobRow(jobId=job.id,groupId=a.groupId,itemId=a.itemId,expectedRevision=a.revision,inputFingerprint="fixture",snapshotJson=inventoryJson(a).toString(),creationKey=newId(),state="SUCCESS",remoteJson="{\"productId\":\"gid://shopify/Product/7\"}");repo.journal.shopifyDao().insert(entry);repo.trashLocal("DRAFT_ITEM",entry.id);assertTrue(repo.journal.shopifyDao().watchItems().first().isEmpty());assertEquals(entry.remoteJson,repo.journal.shopifyDao().item(entry.id)!!.remoteJson);repo.restoreTrash(repo.journal.trashDao().target("DRAFT_ITEM",entry.id)!!.id);assertEquals("SUCCESS",repo.journal.shopifyDao().watchItems().first().single().state);assertEquals("SUCCESS",repo.journal.shopifyDao().job(job.id)!!.state)}
 @Test fun snapshotRetainsTrashAndNineUpgradePreservesUsage():Unit=runBlocking {val a=item();repo.trashLocal("INVENTORY",a.groupId);val snapshot=repo.hashSnapshotFiles(repo.buildSnapshot());assertEquals(10,snapshot.getInt("schema"));assertTrue(snapshot.getJSONObject("tables").getJSONArray("trash_entries").length()>0);val legacy=JSONObject(snapshot.toString()).put("schema",9);legacy.getJSONObject("tables").remove("trash_entries");repo.validateSnapshot(legacy);assertEquals(10,legacy.getInt("schema"))}
 @Test fun legacyRemovedPhotoGetsRecoveryWindowWhenMigrating():Unit=runBlocking {val a=item();val p=repo.dao.photos(a.groupId).single();repo.dao.update(p.copy(deleted=true));val db=repo.journal.openHelper.writableDatabase;db.execSQL("DROP TABLE trash_entries");MIGRATION_9_10.migrate(db);val row=repo.journal.trashDao().target("PHOTO",p.id)!!;assertEquals(TRASH_RETENTION,row.expiresAt-row.deletedAt);repo.restoreTrash(row.id);assertFalse(repo.dao.photo(p.id).deleted)}
 @Test fun remoteDraftHideAndRecoveryOnlyChangeLocalVisibility():Unit=runBlocking {val product=JSONObject().put("id","gid://shopify/Product/12").put("title","Local draft").put("status","DRAFT");val before=product.toString();repo.hideShopifyDraft(product);val entry=repo.journal.trashDao().target("PRODUCT",stableRowId(product.getString("id")))!!;assertEquals(before,product.toString());repo.restoreTrash(entry.id);assertNull(repo.journal.trashDao().target("PRODUCT",entry.targetId));assertEquals(before,product.toString())}
 @Test fun failedDeletionRollsBackAndIndependentlyTrashedPhotoSurvivesBatchRecovery():Unit=runBlocking {val a=item();val p=repo.dao.photos(a.groupId).single();repo.deletePhoto(p.id);val independent=repo.journal.trashDao().target("PHOTO",p.id)!!;val batch=repo.dao.group(a.groupId).sessionId;repo.trashLocal("BATCH",batch);try {repo.restoreTrash(independent.id);fail()} catch(_:IllegalStateException) {};repo.restoreTrash(repo.journal.trashDao().target("BATCH",batch)!!.id);assertTrue(repo.dao.photo(p.id).deleted);assertNotNull(repo.journal.trashDao().get(independent.id));try {repo.trashLocal("INVENTORY",newId());fail()} catch(_:Exception) {};assertEquals(1,repo.journal.inventoryDao().watchItems().first().size);repo.restoreTrash(independent.id);assertFalse(repo.dao.photo(p.id).deleted)}

 @Test fun deletingCurrentRecordMovesCaptureForwardAndUndoNeverReopensTrash():Unit=runBlocking {val a=item();repo.trashLocal("INVENTORY",a.groupId);assertNotEquals(a.groupId,repo.current().id);assertTrue(repo.dao.group(a.groupId).closed);try {repo.undoNext();fail()} catch(_:IllegalStateException) {};val next=repo.reserve();assertNotEquals(a.groupId,next.groupId);assertTrue(repo.journal.inventoryDao().watchItems().first().none {it.groupId==a.groupId})}

 @Test fun nativeAndLegacyAgentReadsExcludeTrashedInventoryAndBatches():Unit=runBlocking {val a=item();val c=ChatConversationRow(title="Trash read fixture",provider="OPENAI",model="fixture",authMode="API_KEY",toolsEnabled=true,proposalsEnabled=false);repo.journal.nextDao().insert(c);val tools=AgentTools(repo);val session=repo.dao.group(a.groupId).sessionId;repo.trashLocal("BATCH",session);val rows=tools.execute(c,"app_read",JSONObject().put("resource","inventory.list").put("arguments_json","{}"));assertEquals(0,rows.getInt("returned"));assertEquals(0,tools.execute(c,"capture_batches",JSONObject().put("offset",0)).getJSONArray("batches").length());try {tools.execute(c,"inventory_get",JSONObject().put("group_id",a.groupId));fail()} catch(_:IllegalStateException) {};repo.restoreTrash(repo.journal.trashDao().target("BATCH",session)!!.id);assertEquals(a.itemId,tools.execute(c,"inventory_get",JSONObject().put("group_id",a.groupId)).getString("itemId"))}

}
